BEGIN;
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), phone TEXT GENERATED ALWAYS AS (payload ->> 'phone') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (phone));
CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), username TEXT GENERATED ALWAYS AS (payload ->> 'username') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (username));
CREATE TABLE IF NOT EXISTS bundles (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), customer_id TEXT GENERATED ALWAYS AS (payload ->> 'customerId') STORED, provider_reference TEXT GENERATED ALWAYS AS (payload ->> 'providerReference') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT payments_customer_fk FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, UNIQUE (provider_reference));
CREATE TABLE IF NOT EXISTS vouchers (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), customer_id TEXT GENERATED ALWAYS AS (payload ->> 'customerId') STORED, payment_id TEXT GENERATED ALWAYS AS (payload ->> 'paymentId') STORED, code TEXT GENERATED ALWAYS AS (payload ->> 'code') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT vouchers_customer_fk FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, CONSTRAINT vouchers_payment_fk FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, UNIQUE (code));
CREATE TABLE IF NOT EXISTS network_sessions (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), voucher_id TEXT GENERATED ALWAYS AS (payload ->> 'voucherId') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT network_sessions_voucher_fk FOREIGN KEY (voucher_id) REFERENCES vouchers(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS dashboard_sessions (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), customer_id TEXT GENERATED ALWAYS AS (payload ->> 'customerId') STORED, token_hash TEXT GENERATED ALWAYS AS (payload ->> 'tokenHash') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT dashboard_sessions_customer_fk FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, UNIQUE (token_hash));
CREATE TABLE IF NOT EXISTS admin_sessions (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), admin_user_id TEXT GENERATED ALWAYS AS (payload ->> 'userId') STORED, token_hash TEXT GENERATED ALWAYS AS (payload ->> 'tokenHash') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT admin_sessions_user_fk FOREIGN KEY (admin_user_id) REFERENCES admin_users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED, UNIQUE (token_hash));
CREATE TABLE IF NOT EXISTS challenges (kind TEXT NOT NULL, id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), customer_id TEXT GENERATED ALWAYS AS (payload ->> 'customerId') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (kind, id), CONSTRAINT challenges_customer_fk FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS events (kind TEXT NOT NULL, id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), event_type TEXT GENERATED ALWAYS AS (payload ->> 'type') STORED, occurred_at TEXT GENERATED ALWAYS AS (payload ->> 'at') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'), PRIMARY KEY (kind, id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL CHECK (ordinal >= 0), action TEXT GENERATED ALWAYS AS (payload ->> 'action') STORED, actor TEXT GENERATED ALWAYS AS (payload ->> 'actor') STORED, occurred_at TEXT GENERATED ALWAYS AS (payload ->> 'at') STORED, payload JSONB NOT NULL CHECK (jsonb_typeof(payload) = 'object'));
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS payments_customer_idx ON payments(customer_id);
CREATE INDEX IF NOT EXISTS vouchers_customer_idx ON vouchers(customer_id);
CREATE INDEX IF NOT EXISTS vouchers_payment_idx ON vouchers(payment_id);
CREATE INDEX IF NOT EXISTS network_sessions_voucher_idx ON network_sessions(voucher_id);
CREATE INDEX IF NOT EXISTS dashboard_sessions_customer_idx ON dashboard_sessions(customer_id);
CREATE INDEX IF NOT EXISTS admin_sessions_user_idx ON admin_sessions(admin_user_id);
CREATE INDEX IF NOT EXISTS challenges_customer_idx ON challenges(customer_id);
CREATE INDEX IF NOT EXISTS challenges_kind_idx ON challenges(kind);
CREATE INDEX IF NOT EXISTS events_kind_occurred_idx ON events(kind, occurred_at DESC);
CREATE INDEX IF NOT EXISTS events_type_idx ON events(event_type);
CREATE INDEX IF NOT EXISTS audit_logs_occurred_idx ON audit_logs(occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_logs_action_idx ON audit_logs(action);
COMMIT;
